function rejected(profile, field) {
  // Every public persistence/reconstruction boundary must retain validation.
  const error = expect.objectContaining({
    code: "BACKGROUND_LAUNCH_PROFILE_INVALID",
    message: `Invalid background launch profile field: ${field}`,
  });
  for (const call of [normalize, canonical, fingerprint, build]) {
    expect(() => call(profile)).toThrowError(error);
  }
}
function pair(path, valid, invalid) {
  const good = capture();
  set(good, path, valid);
  expect(normalize(clone(good))).toEqual(good);
  expect(() => build(clone(good))).not.toThrow();
  const bad = clone(good);
  set(bad, path, invalid); // Only the named condition changes.
  rejected(bad, path);
}

