});
afterEach(() => {
  if (oldHome === undefined) delete process.env.CHAINLESSCHAIN_HOME;
  else process.env.CHAINLESSCHAIN_HOME = oldHome;
  rmSync(dir, { recursive: true, force: true });
});
const capture = (args = []) => captureProfile({ argv: ["agent", ...args], cwd: dir });
const clone = (value) => JSON.parse(JSON.stringify(value));
function set(profile, path, value) {
  const [group, field] = path.split(".");
  if (field) profile[group][field] = value;
  else profile[group] = value;
}
function rejected(profile, field) {
